            print('  ', kk[:80], {x:(str(y)[:60]) for x,y in vv.items() if x in ('home_account_id','username','realm','environment','client_id','target','credential_type')})
" 2>&1 | head -40; echo "--- az.json ---"; head -c 500 az.json; echo; echo "--- config ---"; cat config 2>/dev/null

